--pk-glow-rim: rgba(255, 255, 255, 0.5);

/* The light along the top edge of something raised: a panel's inset highlight, the bevel of a
 * lit button. Quieter than the rim above, and white on both surfaces because it is light
 * falling on the object, not a colour the surface owns. The places that draw it had typed
 * 0.22, 0.25, 0.26, 0.3 and 0.35; nobody chose between them, so they are one weight. */
--pk-lit-edge: rgba(255, 255, 255, 0.22);

/* Lime as light rather than as a fill: the halo under the glow button, and the same halo under
 * the cursor. Two weights, because resting and hovered have to be told apart; every other lime
 * glow in the product takes the nearer of the two. */
--pk-glow-lime: rgba(200, 240, 58, 0.32);
--pk-glow-lime-strong: rgba(200, 240, 58, 0.5);

/* What a dialog dims the page with. The dark ground at a fraction, on both surfaces: a scrim
 * darkens whatever is behind it, and a light one would wash a light page out instead. */
--pk-scrim: rgba(11, 13, 26, 0.72);
